#!/bin/sh
# PhoneHop router setup for OpenWrt and OpenWrt-based firmware such as GL.iNet.
# Generated by the app from a template.
#
# THIS ERASES THE ROUTER'S CONFIGURATION (a full backup is taken first) and rebuilds it for one job:
# join the phone's Wi-Fi Direct network, send ALL client traffic through a WireGuard tunnel whose
# endpoint is the phone (which relays it to Mullvad), and block clients from reaching the internet
# any other way, so nothing leaks if the tunnel is down. Installed packages and the admin password
# are kept. Nothing is changed unless every safety check below passes.
SSID=@@SSID@@
PSK=@@PSK@@
PREFER_5G=@@PREFER_5G@@
WG_KEY=@@WG_PRIVATE_KEY@@
WG_V4=@@WG_ADDRESS_V4@@
WG_V6=@@WG_ADDRESS_V6@@
SERVER_PUB=@@SERVER_PUBLIC_KEY@@
RELAY_HOST=@@RELAY_HOST@@
RELAY_PORT=@@RELAY_PORT@@
PHONE_ADDR=@@PHONE_ADDRESS@@
DNS=@@DNS@@
CLIENT_SSID=@@CLIENT_SSID@@
CLIENT_PSK=@@CLIENT_PSK@@
COUNTRY=@@COUNTRY@@
LAN_IP=@@LAN_IP@@
LAN_MASK=@@LAN_MASK@@
DHCP_START=@@DHCP_START@@
DHCP_LIMIT=@@DHCP_LIMIT@@
NOW=@@NOW@@
ROLLBACK=@@ROLLBACK_SECONDS@@

CFG=${PH_CFG:-/etc/config}
ROM=${PH_ROM:-/rom/etc/config}
CONFIG_GENERATE=${PH_CONFIG_GENERATE:-config_generate}
INITD=${PH_INITD:-/etc/init.d}
BK=${PH_BK:-/root/phonehop-backup}
REVERT=${PH_REVERT:-/root/phonehop-revert.sh}
PENDING=${PH_PENDING:-/tmp/phonehop-pending}

fail() { echo "PHONEHOP_ERROR: $1" >&2; exit 1; }
u() { uci "$@" || fail "uci $1 failed"; }
ud() { uci -q delete "$1" >/dev/null 2>&1; true; }

# ---- 0. Safety checks. Everything here runs BEFORE anything is erased; a failure changes nothing.
command -v uci >/dev/null 2>&1 || fail "uci not found; this does not look like OpenWrt"
command -v tar >/dev/null 2>&1 || fail "tar not found; cannot back up the configuration"
command -v wg >/dev/null 2>&1 || fail "WireGuard tools are not installed on this router (install wireguard-tools and kmod-wireguard first; a wipe keeps installed packages)"
[ -d /sys/module/wireguard ] || modprobe wireguard >/dev/null 2>&1 || fail "WireGuard kernel support is missing"
[ -d "$ROM" ] || fail "no factory defaults at $ROM; this firmware layout is not supported for a safe wipe"
command -v "$CONFIG_GENERATE" >/dev/null 2>&1 || fail "config_generate not found; cannot rebuild the default network settings"
command -v wifi >/dev/null 2>&1 || fail "wifi command not found"

# ---- 1. Full backup of the current configuration (once, so Revert always returns to the true original).
if [ ! -f "$BK/config.tgz" ]; then
  mkdir -p "$BK" || fail "cannot create $BK"
  tar czf "$BK/config.tgz" -C "$CFG" . || fail "could not back up the configuration"
fi
echo "PHONEHOP_BACKUP=$BK/config.tgz"
cat > "$REVERT" <<'PHONEHOP_REVERT_EOF'
@@REVERT_BODY@@
PHONEHOP_REVERT_EOF
chmod +x "$REVERT"

# ---- 2. Clock. These routers have no battery clock, and WireGuard needs a sane time.
date -u -s "$NOW" >/dev/null 2>&1 || echo "PHONEHOP_WARN=could not set the clock"

# ---- 2b. WIPE. Every config file goes back to the firmware's factory default, or is deleted if the
# firmware has no default for it; network and Wi-Fi settings are regenerated for this hardware.
echo PHONEHOP_WIPING=1
for f in "$CFG"/*; do
  [ -e "$f" ] || continue
  b=$(basename "$f")
  if [ -f "$ROM/$b" ]; then cp "$ROM/$b" "$f"; else rm -f "$f"; fi
done
rm -f "$CFG/network" "$CFG/wireless" "$CFG/system"
touch "$CFG/network" "$CFG/system"
"$CONFIG_GENERATE" >/dev/null 2>&1 || fail "config_generate failed; the router may be half-reset. Run Revert"
wifi config >/dev/null 2>&1 || wifi detect > "$CFG/wireless" 2>/dev/null
echo PHONEHOP_WIPED

# ---- 3. Pick the radio that will talk to the phone (5 GHz if asked for and present).
radio_band() {
  b=$(uci -q get "wireless.$1.band")
  case "$b" in 5g) echo 5g; return;; 2g) echo 2g; return;; esac
  h=$(uci -q get "wireless.$1.hwmode")
  case "$h" in 11a) echo 5g; return;; 11g|11b|11ng) echo 2g; return;; esac
  c=$(uci -q get "wireless.$1.channel")
  if [ "$c" -gt 14 ] 2>/dev/null; then echo 5g; else echo 2g; fi
}
RADIO=""
RBAND=""
FIRST=""
for r in $(uci show wireless | sed -n 's/^wireless\.\([^.=]*\)=wifi-device$/\1/p'); do
  [ -z "$FIRST" ] && FIRST=$r
  b=$(radio_band "$r")
  if [ -z "$RADIO" ]; then
    if [ "$PREFER_5G" = 1 ] && [ "$b" = 5g ]; then RADIO=$r; RBAND=$b; fi
    if [ "$PREFER_5G" != 1 ] && [ "$b" = 2g ]; then RADIO=$r; RBAND=$b; fi
  fi
done
if [ -z "$RADIO" ]; then RADIO=$FIRST; [ -n "$FIRST" ] && RBAND=$(radio_band "$FIRST"); fi
[ -n "$RADIO" ] || fail "no Wi-Fi radio found"
echo "PHONEHOP_RADIO=$RADIO ($RBAND)"
for r in $(uci show wireless | sed -n 's/^wireless\.\([^.=]*\)=wifi-device$/\1/p'); do
  u set "wireless.$r.disabled=0"
  [ -n "$COUNTRY" ] && u set "wireless.$r.country=$COUNTRY"
done

# ---- 4. Join the phone's Wi-Fi Direct network as a client.
# Switch off other client-mode networks (e.g. a GL.iNet repeater) so they do not fight over the radio.
for s in $(uci show wireless | sed -n "s/^wireless\.\([^.=]*\)\.mode='sta'\$/\1/p"); do
  [ "$s" = phonehop_sta ] || uci set "wireless.$s.disabled=1"
done
ud wireless.phonehop_sta
u set wireless.phonehop_sta=wifi-iface
u set "wireless.phonehop_sta.device=$RADIO"
u set wireless.phonehop_sta.mode=sta
u set wireless.phonehop_sta.network=phonehop
u set "wireless.phonehop_sta.ssid=$SSID"
u set wireless.phonehop_sta.encryption=psk2
u set "wireless.phonehop_sta.key=$PSK"
u set wireless.phonehop_sta.disabled=0
u set "wireless.$RADIO.disabled=0"

# Your own Wi-Fi: the firmware's default networks (with their well-known default passwords) are removed
# and one is created per radio. The two bands are separate networks, named <name>_5G and <name>_2.4G,
# so every device can be told exactly which band to use.
for s in $(uci show wireless | sed -n "s/^wireless\.\([^.=]*\)\.mode='ap'\$/\1/p"); do
  uci delete "wireless.$s" >/dev/null 2>&1
done
for r in $(uci show wireless | sed -n 's/^wireless\.\([^.=]*\)=wifi-device$/\1/p'); do
  case "$(radio_band "$r")" in 5g) SUFFIX=_5G;; *) SUFFIX=_2.4G;; esac
  u set "wireless.phonehop_ap_$r=wifi-iface"
  u set "wireless.phonehop_ap_$r.device=$r"
  u set "wireless.phonehop_ap_$r.mode=ap"
  u set "wireless.phonehop_ap_$r.network=lan"
  u set "wireless.phonehop_ap_$r.ssid=$CLIENT_SSID$SUFFIX"
  u set "wireless.phonehop_ap_$r.encryption=psk2"
  u set "wireless.phonehop_ap_$r.key=$CLIENT_PSK"
  u set "wireless.phonehop_ap_$r.disabled=0"
  echo "PHONEHOP_WIFI_$r=$CLIENT_SSID$SUFFIX"
done

# ---- 4b. The router's own address range, as chosen by the user.
ud network.lan.ipaddr
ud network.lan.netmask
u set "network.lan.ipaddr=$LAN_IP"
u set "network.lan.netmask=$LAN_MASK"
uci -q get dhcp.lan >/dev/null 2>&1 || { u set dhcp.lan=dhcp; u set dhcp.lan.interface=lan; }
u set "dhcp.lan.start=$DHCP_START"
u set "dhcp.lan.limit=$DHCP_LIMIT"
u set dhcp.lan.leasetime=12h
echo "PHONEHOP_LAN=$LAN_IP/$LAN_MASK"

# ---- 5. The link to the phone. No default route and no DNS from it: it cannot reach the internet itself.
ud network.wan6
ud network.phonehop
u set network.phonehop=interface
u set network.phonehop.proto=dhcp
u set network.phonehop.defaultroute=0
u set network.phonehop.peerdns=0

# ---- 6. WireGuard tunnel to the VPN server, with the phone as the UDP endpoint.
ud network.mullvad_peer
ud network.mullvad
u set network.mullvad=interface
u set network.mullvad.proto=wireguard
u set "network.mullvad.private_key=$WG_KEY"
u set network.mullvad.mtu=1380
u add_list "network.mullvad.addresses=$WG_V4"
[ -n "$WG_V6" ] && u add_list "network.mullvad.addresses=$WG_V6"
u set network.mullvad_peer=wireguard_mullvad
u set network.mullvad_peer.description=PhoneHop
u set "network.mullvad_peer.public_key=$SERVER_PUB"
u set "network.mullvad_peer.endpoint_host=$RELAY_HOST"
u set "network.mullvad_peer.endpoint_port=$RELAY_PORT"
u set network.mullvad_peer.persistent_keepalive=25
u set network.mullvad_peer.route_allowed_ips=1
u add_list network.mullvad_peer.allowed_ips=0.0.0.0/0
u add_list network.mullvad_peer.allowed_ips=::/0

# ---- 7. Firewall: clients may only leave through the tunnel (the kill switch).
ud firewall.phonehop_vpn
ud firewall.phonehop_lan_vpn
ud firewall.phonehop_ssh
u set firewall.phonehop_vpn=zone
u set firewall.phonehop_vpn.name=vpn
u set firewall.phonehop_vpn.network=mullvad
u set firewall.phonehop_vpn.input=REJECT
u set firewall.phonehop_vpn.output=ACCEPT
u set firewall.phonehop_vpn.forward=REJECT
u set firewall.phonehop_vpn.masq=1
u set firewall.phonehop_vpn.mtu_fix=1
u set firewall.phonehop_lan_vpn=forwarding
u set firewall.phonehop_lan_vpn.src=lan
u set firewall.phonehop_lan_vpn.dest=vpn
# Remove LAN -> WAN forwarding (highest index first, since uci renumbers after each delete).
for i in $(uci show firewall | sed -n "s/^firewall\.@forwarding\[\([0-9]*\)\]\.src='lan'\$/\1/p" | sort -rn); do
  d=$(uci -q get "firewall.@forwarding[$i].dest")
  [ "$d" = wan ] && uci delete "firewall.@forwarding[$i]"
done
# Treat the phone link as WAN, and let only the phone reach SSH over it (for later management).
WANZ=$(uci show firewall | sed -n "s/^firewall\.\(@zone\[[0-9]*\]\)\.name='wan'\$/\1/p" | head -1)
[ -n "$WANZ" ] || fail "no wan firewall zone found"
uci -q del_list "firewall.$WANZ.network=phonehop" >/dev/null 2>&1
u add_list "firewall.$WANZ.network=phonehop"
u set firewall.phonehop_ssh=rule
u set firewall.phonehop_ssh.name=PhoneHop-SSH
u set firewall.phonehop_ssh.src=wan
u set "firewall.phonehop_ssh.src_ip=$PHONE_ADDR"
u set firewall.phonehop_ssh.dest_port=22
u set firewall.phonehop_ssh.proto=tcp
u set firewall.phonehop_ssh.target=ACCEPT

# ---- 8. DNS only through the tunnel; SSH reachable on the phone link (not just the LAN).
ud "dhcp.@dnsmasq[0].server"
u add_list "dhcp.@dnsmasq[0].server=$DNS"
u set "dhcp.@dnsmasq[0].noresolv=1"
ud "dropbear.@dropbear[0].Interface"

# ---- 9. Save and apply. Applying in the background lets this SSH session finish cleanly.
for f in wireless network firewall dhcp dropbear; do
  uci commit "$f" || fail "uci commit $f failed"
done
touch "$PENDING"
# If the phone link never comes up and nobody confirms, put the old settings back.
( sleep "$ROLLBACK"; [ -f "$PENDING" ] && sh "$REVERT" ) </dev/null >/dev/null 2>&1 &
( sleep 3
  command -v reload_config >/dev/null 2>&1 && reload_config
  "$INITD/dropbear" restart; wifi reload; "$INITD/network" reload; "$INITD/firewall" reload; "$INITD/dnsmasq" restart
) </dev/null >/dev/null 2>&1 &
command -v base64 >/dev/null 2>&1 && echo "PHONEHOP_BACKUP_B64=$(base64 "$BK/config.tgz" | tr -d '\n')"
echo PHONEHOP_APPLIED
